commands.command:
sudo tee /etc/nginx/nginx.conf >/dev/null <<'ANTRIEB_NGINX'
user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log notice;
pid /run/nginx.pid;
events { worker_connections 1024; }
http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    log_format main '$remote_addr - $remote_user [$time_local] "$request" $status $body_bytes_sent';
    access_log /var/log/nginx/access.log main;
    sendfile on;
    upstream inventory_backends {
        server 10.100.27.11:8080;
        server 10.100.27.12:8080;
    }
    server {
        listen 80 default_server;
        server_name _;
        location / {
            proxy_pass http://inventory_backends;
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            add_header X-Load-Balancer node1 always;
        }
    }
}
ANTRIEB_NGINX
sudo nginx -t && sudo setsebool -P httpd_can_network_connect 1 && sudo firewall-cmd --permanent --add-service=http && sudo firewall-cmd --add-service=http && sudo systemctl enable --now nginx

